import CMigration

import Darwin

extension hexdump {
  func newsyntax(_ opts : inout CommandOptions) throws {
    
    // See if the command was called as "hd" -- which implies "-C"
    let farg = CommandLine.arguments[0]
    if farg.hasSuffix("hd") {
      /* "Canonical" format, implies -C. */
      add("\"%08.8_Ax\n\"")
      add("\"%08.8_ax  \" 8/1 \"%02x \" \"  \" 8/1 \"%02x \" ")
      add("\"  |\" 16/1 \"%_p\" \"|\\n\"")
    }
    
    let go = BSDGetopt("bcCde:f:n:os:vx")
    
      while let (ch, optarg) = try go.getopt() {
      
//      let chx = getopt(argc, argv, "bcCde:f:n:os:vx")
//      if chx == EOF { break }
//      let ch = Character.from(UInt8(chx))
      switch (ch) {
      case "b":
        add("\"%07.7_Ax\n\"")
        add("\"%07.7_ax \" 16/1 \"%03o \" \"\\n\"")
      case "c":
        add("\"%07.7_Ax\n\"")
        add("\"%07.7_ax \" 16/1 \"%3_c \" \"\\n\"")
      case "C":
        add("\"%08.8_Ax\n\"")
        add("\"%08.8_ax  \" 8/1 \"%02x \" \"  \" 8/1 \"%02x \" ")
        add("\"  |\" 16/1 \"%_p\" \"|\\n\"")
      case "d":
        add("\"%07.7_Ax\n\"")
        add("\"%07.7_ax \" 8/2 \"  %05u \" \"\\n\"")
      case "e":
        add(optarg)
      case "f":
        try addfile(optarg)
      case "n":
        let oa = optarg
        // atoi(3): anything that isn't a leading number counts as 0
        let length = Int(atoi(oa))
        if length < 0 {
          errx(1, "\(oa): bad length value")
        }
        self.length = length
      case "o":
        add("\"%07.7_Ax\n\"")
        add("\"%07.7_ax \" 8/2 \" %06o \" \"\\n\"")
      case "s":
        let oa = optarg
        // the suffix is whatever follows the number, so it has to be read while the C string is alive
        var (lskip, suffix) : (Int64, Character?) = oa.withCString { cs in
          var end: UnsafeMutablePointer<CChar>? = nil
          let v = strtoll(cs, &end, 0)
          if let end, end.pointee != 0 {
            return (v, Character(UnicodeScalar(UInt8(bitPattern: end.pointee))))
          }
          return (v, nil)
        }
        if lskip < 0 {
          errx(1, "\(oa): bad skip value")
        }
        switch suffix {
        case "b":
          lskip *= 512
        case "k":
          lskip *= 1024
        case "m":
          lskip *= 1048576
        case "g":
          lskip *= 1073741824
        default:
          break
        }
        skip = lskip
      case "v":
          opts.vflag = .ALL
      case "x":
        add("\"%07.7_Ax\n\"")
        add("\"%07.7_ax \" 8/2 \"   %04x \" \"\\n\"")
      case "?":
        throw CmdErr(1)
      default:
        break
      }
    }
    
    if fsArray.count == 0 {
      add("\"%07.7_Ax\n\"")
      add("\"%07.7_ax \" 8/2 \"%04x \" \"\\n\"")
    }
    
      opts.args = ArraySlice(go.remaining)
  }
                                   
  
}
